def test_vowels_consonants():
    res = count_vowels_and_consonants("Hello, World!")
    assert res == {"vowels": 3, "consonants": 7}

def test_empty():
    assert count_vowels_and_consonants("") == {"vowels": 0, "consonants": 0}

def test_digits_and_symbols():
    assert count_vowels_and_consonants("12345!@#$") == {"vowels": 0, "consonants": 0}

def test_merge_basic():
    assert merge_intervals([[1,3],[2,6],[8,10],[15,18]]) == [[1,6],[8,10],[15,18]]

def test_merge_touching():
    assert merge_intervals([[1,4],[4,5]]) == [[1,5]]

def test_empty_and_single():
    assert merge_intervals([]) == []
    assert merge_intervals([[1,4]]) == [[1,4]]

def test_unsorted_input():
    assert merge_intervals([[5,8],[1,3],[2,4]]) == [[1,4],[5,8]]

def test_nested_and_identical():
    assert merge_intervals([[1, 10], [2, 3], [4, 5]]) == [[1, 10]]
    assert merge_intervals([[1, 4], [2, 3]]) == [[1, 4]]
    assert merge_intervals([[2, 3], [4, 5], [1, 4]]) == [[1, 5]]

