def test_flatten():
    data = {'a': 1, 'b': {'c': 2, 'd': {'e': 3}}}
    expected = {'a': 1, 'b.c': 2, 'b.d.e': 3}
    assert flatten_dict(data) == expected

def test_custom_sep():
    data = {'user': {'name': 'Alice'}}
    assert flatten_dict(data, sep='/') == {'user/name': 'Alice'}

def test_flat_input():
    assert flatten_dict({'x': 10, 'y': 20}) == {'x': 10, 'y': 20}
    assert flatten_dict({}) == {}

def test_prefix_common():
    assert longest_common_prefix(["flower","flow","flight"]) == "fl"

def test_prefix_none():
    assert longest_common_prefix(["dog","racecar","car"]) == ""

def test_prefix_empty_list():
    assert longest_common_prefix([]) == ""

def test_prefix_single():
    assert longest_common_prefix(["alone"]) == "alone"

def test_prefix_exact():
    assert longest_common_prefix(["test","test","test"]) == "test"

def test_rpn_simple():
    assert evaluate_rpn(["2", "1", "+", "3", "*"]) == 9
    assert evaluate_rpn(["4", "13", "5", "/", "+"]) == 6

def test_rpn_truncation():
    assert evaluate_rpn(["10", "6", "9", "3", "+", "-11", "*", "/", "*", "17", "+", "5", "+"]) == 22
    assert evaluate_rpn(["7", "-3", "/"]) == -2

def test_rpn_negative_division():
    assert evaluate_rpn(["-7", "3", "/"]) == -2
    assert evaluate_rpn(["1", "-2", "/"]) == 0
    assert evaluate_rpn(["-1", "2", "/"]) == 0

def test_merge_immutability():
    d1 = {'a': 1, 'b': {'c': [1, 2]}, 'd': {'nested': 10}}
    d2 = {'b': {'c': [3, 4], 'extra': 5}, 'd': {'nested': 20}}
    d1_copy = {'a': 1, 'b': {'c': [1, 2]}, 'd': {'nested': 10}}
    res = deep_merge_immutable(d1, d2)
    assert d1 == d1_copy, 'Original base dict was mutated!'
    assert res == {'a': 1, 'b': {'c': [1, 2, 3, 4], 'extra': 5}, 'd': {'nested': 20}}
    res['b']['c'].append(999)
    assert d1['b']['c'] == [1, 2], 'Mutating result affected original base list!'

def test_basic_tokenizing():
    assert custom_tokenizer("a,b;c", ",;") == ["a", "b", "c"]

def test_escaped_delimiters():
    assert custom_tokenizer(r"a\,b,c", ",") == ["a,b", "c"]
    assert custom_tokenizer(r"hello\\world,test", ",") == ["hello\\world", "test"]

def test_consecutive_delimiters():
    assert custom_tokenizer("a,,b", ",") == ["a", "", "b"]
    assert custom_tokenizer(",", ",") == ["", ""]

def test_escaped_escape_before_delimiter():
    assert custom_tokenizer(r"a\\,b", ",") == ["a\\", "b"]
